INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','past-perfect-continuous','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"past-perfect-continuous","title":"Past perfect continuous","level":"B2","order":33,"summary":"The past perfect continuous describes an activity leading up to a past moment. It can explain a past condition: someone was tired because they had been working. The simple perfect often foregrounds completion; the continuous foregrounds the activity and its duration.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Focus on the activity","Keep both auxiliaries","Questions and negatives","State verbs and completed quantities"],"rules":[{"title":"Focus on the activity","explanation":"The past perfect continuous describes an activity leading up to a past moment. It can explain a past condition: someone was tired because they had been working. The simple perfect often foregrounds completion; the continuous foregrounds the activity and its duration.","pattern":"Subject + **had been + -ing**","commonMistakes":["A continuous form does not guarantee that the activity is unfinished; context can show that it recently stopped."],"examples":["Use the past perfect continuous: She **had been preparing** the visitor guide for an hour before lunch yesterday.","Use the past perfect continuous: She **had been restoring** the old portrait for an hour before lunch yesterday."],"skill":"form"},{"title":"Keep both auxiliaries","explanation":"The construction has three verb parts: **had or had**, then **been**, then an **-ing** form. Only the first auxiliary changes with tense and subject. Been is the past participle of be; it connects perfect aspect with the continuous construction.","pattern":"She **had been working**.","commonMistakes":["Do not omit been or change it to being in this construction."],"examples":["Make a past-perfect-continuous negative: We **had not been preparing** the visitor guide all morning before lunch yesterday.","Make a past-perfect-continuous negative: We **had not been restoring** the old portrait all morning before lunch yesterday."],"skill":"meaning"},{"title":"Questions and negatives","explanation":"Move only **had or had** before the subject in questions. Put not after that same auxiliary in negatives. Been and the -ing form remain in place. A short answer repeats only the first auxiliary.","pattern":"Had they **been working**?","commonMistakes":["Have been they working? puts too much of the verb phrase before the subject."],"examples":["Complete the past-perfect-continuous question: Had they **been preparing** the visitor guide for long before lunch yesterday?","Complete the past-perfect-continuous question: Had they **been restoring** the old portrait for long before lunch yesterday?"],"skill":"contrast"},{"title":"State verbs and completed quantities","explanation":"Know, own and believe usually describe states and favour perfect simple: I have known her for years. A completed count also favours the simple: I have written three reports. Repeated activity can use continuous: I have been writing reports all morning. The meaning of the verb matters, not just a time expression.","pattern":"I have **known** her for years. / I have **been waiting** for an hour.","commonMistakes":["For and since can accompany simple perfect states; they do not automatically require continuous."],"examples":["Choose the past perfect SIMPLE, focusing on completion: I **had prepared** the visitor guide before lunch yesterday.","Choose the past perfect SIMPLE, focusing on completion: I **had restored** the old portrait before lunch yesterday."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"53181c33-954f-5080-a59b-e3f2228e90a2","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Use the past perfect continuous: She ____ the visitor guide for an hour before lunch yesterday.","choices":[{"id":"A","text":"had been preparing"},{"id":"B","text":"had preparing"},{"id":"C","text":"had being preparing"},{"id":"D","text":"had been prepared"}],"answerId":"A","hint":"An activity lasting for a period calls for the requested **perfect + continuous** form.","explanation":"Build **had + been + preparing**. The sentence focuses on the duration of the activity before lunch yesterday.","keywords":["continuous-affirmative"],"skill":"continuous-affirmative","contextKey":"past-perfect-continuous-1","fingerprint":"bcc99d8b950e3f7aefa187b21003cfa303dc3ccb45e27ba0a7b2815cb54bb3c0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["An activity lasting for a period calls for the requested **perfect + continuous** form.","Build **had + been + preparing**. The sentence focuses on the duration of the activity before lunch yesterday.","Choose **had been preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Build **had + been + preparing**. The sentence focuses on the duration of the activity before lunch yesterday.","B":"Been is missing between the perfect auxiliary and the -ing form.","C":"The perfect auxiliary requires been, not being.","D":"A past participle here would suggest passive voice rather than the requested active continuous."}}},{"id":"d90ea56e-c921-54a7-ac28-c82bbef6e8ff","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Make a past-perfect-continuous negative: We ____ the visitor guide all morning before lunch yesterday.","choices":[{"id":"A","text":"had been not preparing"},{"id":"B","text":"had not preparing"},{"id":"C","text":"did not been preparing"},{"id":"D","text":"had not been preparing"}],"answerId":"D","hint":"Put **not after the first auxiliary** and retain the rest of the verb phrase.","explanation":"Put not after **had**, before **been preparing**.","keywords":["continuous-negative"],"skill":"continuous-negative","contextKey":"past-perfect-continuous-1","fingerprint":"5ee202d5858213ce0bba5e6ef1fbbb4f5aaf10e684cc5e632e6619a05fa27113","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Put **not after the first auxiliary** and retain the rest of the verb phrase.","Put not after **had**, before **been preparing**.","Choose **had not been preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The ordinary negative position is after the first auxiliary, before been.","B":"Been is missing.","C":"Did cannot combine with been to make a perfect continuous negative.","D":"Put not after **had**, before **been preparing**."}}},{"id":"af124beb-89e4-5fec-a80c-7a25835cf932","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Complete the past-perfect-continuous question: Had they ____ the visitor guide for long before lunch yesterday?","choices":[{"id":"A","text":"been preparing"},{"id":"B","text":"being preparing"},{"id":"C","text":"been prepare"},{"id":"D","text":"preparing"}],"answerId":"A","hint":"The first auxiliary has already moved. Supply **been + -ing** after the subject.","explanation":"The first auxiliary is already at the front. After they, keep **been + preparing**.","keywords":["continuous-question"],"skill":"continuous-question","contextKey":"past-perfect-continuous-1","fingerprint":"db4b4e7d18a08b0ad50bdacd2c09f94c0742f530a18331864b84fd4ab7f3ac99","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first auxiliary has already moved. Supply **been + -ing** after the subject.","The first auxiliary is already at the front. After they, keep **been + preparing**.","Choose **been preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The first auxiliary is already at the front. After they, keep **been + preparing**.","B":"The perfect auxiliary requires been, not being.","C":"The active continuous part requires -ing, not the base form.","D":"The linking auxiliary been is missing."}}},{"id":"f16340c9-7c80-5125-a30e-54f068e40e08","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Choose the past perfect SIMPLE, focusing on completion: I ____ the visitor guide before lunch yesterday.","choices":[{"id":"A","text":"had prepared"},{"id":"B","text":"had been preparing"},{"id":"C","text":"had preparing"},{"id":"D","text":"had to prepare"}],"answerId":"A","hint":"Separate **completion** from **duration**. The requested form is perfect simple.","explanation":"The instruction focuses on a completed result, so use the simple perfect **had prepared**.","keywords":["simple-continuous-contrast"],"skill":"simple-continuous-contrast","contextKey":"past-perfect-continuous-1","fingerprint":"a6cb9d3349f5ff123c117cd019c2d9483c05de6ec2efa4ac1e4c56c3b2b23e3d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Separate **completion** from **duration**. The requested form is perfect simple.","The instruction focuses on a completed result, so use the simple perfect **had prepared**.","Choose **had prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The instruction focuses on a completed result, so use the simple perfect **had prepared**.","B":"This is perfect continuous, which foregrounds the activity rather than the requested simple form.","C":"This omits been and is not a complete perfect continuous form.","D":"Have as a perfect auxiliary cannot take a to-infinitive."}}},{"id":"64769c12-4a86-50a4-af2a-317662c0f3d0","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Use the past perfect continuous: She ____ the old portrait for an hour before lunch yesterday.","choices":[{"id":"A","text":"had being restoring"},{"id":"B","text":"had been restored"},{"id":"C","text":"had been restoring"},{"id":"D","text":"had restoring"}],"answerId":"C","hint":"An activity lasting for a period calls for the requested **perfect + continuous** form.","explanation":"Build **had + been + restoring**. The sentence focuses on the duration of the activity before lunch yesterday.","keywords":["continuous-affirmative"],"skill":"continuous-affirmative","contextKey":"past-perfect-continuous-2","fingerprint":"dbdd5aea3e593a8e724cb9d16628bb577e5742454aba4a9e9bd4df7fcaae4df1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["An activity lasting for a period calls for the requested **perfect + continuous** form.","Build **had + been + restoring**. The sentence focuses on the duration of the activity before lunch yesterday.","Choose **had been restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The perfect auxiliary requires been, not being.","B":"A past participle here would suggest passive voice rather than the requested active continuous.","C":"Build **had + been + restoring**. The sentence focuses on the duration of the activity before lunch yesterday.","D":"Been is missing between the perfect auxiliary and the -ing form."}}},{"id":"490ca5df-2e6d-5bec-a68f-e9f6e8f31966","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Make a past-perfect-continuous negative: We ____ the old portrait all morning before lunch yesterday.","choices":[{"id":"A","text":"did not been restoring"},{"id":"B","text":"had not been restoring"},{"id":"C","text":"had been not restoring"},{"id":"D","text":"had not restoring"}],"answerId":"B","hint":"Put **not after the first auxiliary** and retain the rest of the verb phrase.","explanation":"Put not after **had**, before **been restoring**.","keywords":["continuous-negative"],"skill":"continuous-negative","contextKey":"past-perfect-continuous-2","fingerprint":"4655b603c744b9ce69bd358958b9ecf9bf2263d909ae51f2d1f01523d65f4568","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Put **not after the first auxiliary** and retain the rest of the verb phrase.","Put not after **had**, before **been restoring**.","Choose **had not been restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Did cannot combine with been to make a perfect continuous negative.","B":"Put not after **had**, before **been restoring**.","C":"The ordinary negative position is after the first auxiliary, before been.","D":"Been is missing."}}},{"id":"4e626966-8e89-5699-aedd-960ed972188e","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Complete the past-perfect-continuous question: Had they ____ the old portrait for long before lunch yesterday?","choices":[{"id":"A","text":"been restore"},{"id":"B","text":"restoring"},{"id":"C","text":"been restoring"},{"id":"D","text":"being restoring"}],"answerId":"C","hint":"The first auxiliary has already moved. Supply **been + -ing** after the subject.","explanation":"The first auxiliary is already at the front. After they, keep **been + restoring**.","keywords":["continuous-question"],"skill":"continuous-question","contextKey":"past-perfect-continuous-2","fingerprint":"d40670c2815b61fad32a76e6d4931a46b2161d7dacfc33ca32cd058316d7deb2","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first auxiliary has already moved. Supply **been + -ing** after the subject.","The first auxiliary is already at the front. After they, keep **been + restoring**.","Choose **been restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The active continuous part requires -ing, not the base form.","B":"The linking auxiliary been is missing.","C":"The first auxiliary is already at the front. After they, keep **been + restoring**.","D":"The perfect auxiliary requires been, not being."}}},{"id":"6e2dccaf-7506-5c59-adec-5eac9d6d1750","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Choose the past perfect SIMPLE, focusing on completion: I ____ the old portrait before lunch yesterday.","choices":[{"id":"A","text":"had restored"},{"id":"B","text":"had been restoring"},{"id":"C","text":"had restoring"},{"id":"D","text":"had to restore"}],"answerId":"A","hint":"Separate **completion** from **duration**. The requested form is perfect simple.","explanation":"The instruction focuses on a completed result, so use the simple perfect **had restored**.","keywords":["simple-continuous-contrast"],"skill":"simple-continuous-contrast","contextKey":"past-perfect-continuous-2","fingerprint":"66100c7e11d2555aec24de40b786d647bb6ac101264d82d3135b0f53cc4238d2","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Separate **completion** from **duration**. The requested form is perfect simple.","The instruction focuses on a completed result, so use the simple perfect **had restored**.","Choose **had restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The instruction focuses on a completed result, so use the simple perfect **had restored**.","B":"This is perfect continuous, which foregrounds the activity rather than the requested simple form.","C":"This omits been and is not a complete perfect continuous form.","D":"Have as a perfect auxiliary cannot take a to-infinitive."}}},{"id":"aabc8414-3166-536b-a135-5af3fe6ede05","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Use the past perfect continuous: She ____ the garden fence for an hour before lunch yesterday.","choices":[{"id":"A","text":"had been measuring"},{"id":"B","text":"had measuring"},{"id":"C","text":"had being measuring"},{"id":"D","text":"had been measured"}],"answerId":"A","hint":"An activity lasting for a period calls for the requested **perfect + continuous** form.","explanation":"Build **had + been + measuring**. The sentence focuses on the duration of the activity before lunch yesterday.","keywords":["continuous-affirmative"],"skill":"continuous-affirmative","contextKey":"past-perfect-continuous-3","fingerprint":"c139b2abd331694ba38c5fba00b25ce70c97d719cadebbc632bafa1379ca5d62","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["An activity lasting for a period calls for the requested **perfect + continuous** form.","Build **had + been + measuring**. The sentence focuses on the duration of the activity before lunch yesterday.","Choose **had been measuring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Build **had + been + measuring**. The sentence focuses on the duration of the activity before lunch yesterday.","B":"Been is missing between the perfect auxiliary and the -ing form.","C":"The perfect auxiliary requires been, not being.","D":"A past participle here would suggest passive voice rather than the requested active continuous."}}},{"id":"779e3520-d455-5dc0-adb4-3377690545ca","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Make a past-perfect-continuous negative: We ____ the garden fence all morning before lunch yesterday.","choices":[{"id":"A","text":"had not been measuring"},{"id":"B","text":"had been not measuring"},{"id":"C","text":"had not measuring"},{"id":"D","text":"did not been measuring"}],"answerId":"A","hint":"Put **not after the first auxiliary** and retain the rest of the verb phrase.","explanation":"Put not after **had**, before **been measuring**.","keywords":["continuous-negative"],"skill":"continuous-negative","contextKey":"past-perfect-continuous-3","fingerprint":"66afddd4203b6202911d4f41d8e838f45d637d3163f6b9e811d7da18fcd77e61","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Put **not after the first auxiliary** and retain the rest of the verb phrase.","Put not after **had**, before **been measuring**.","Choose **had not been measuring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Put not after **had**, before **been measuring**.","B":"The ordinary negative position is after the first auxiliary, before been.","C":"Been is missing.","D":"Did cannot combine with been to make a perfect continuous negative."}}},{"id":"a6c686c9-7a1a-5e72-aef5-376b445a6f6f","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Complete the past-perfect-continuous question: Had they ____ the garden fence for long before lunch yesterday?","choices":[{"id":"A","text":"been measure"},{"id":"B","text":"measuring"},{"id":"C","text":"been measuring"},{"id":"D","text":"being measuring"}],"answerId":"C","hint":"The first auxiliary has already moved. Supply **been + -ing** after the subject.","explanation":"The first auxiliary is already at the front. After they, keep **been + measuring**.","keywords":["continuous-question"],"skill":"continuous-question","contextKey":"past-perfect-continuous-3","fingerprint":"b319d272cba6579bff4d4d85e120ac2f7d26da1790e65ebd41e382b999ff8d45","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first auxiliary has already moved. Supply **been + -ing** after the subject.","The first auxiliary is already at the front. After they, keep **been + measuring**.","Choose **been measuring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The active continuous part requires -ing, not the base form.","B":"The linking auxiliary been is missing.","C":"The first auxiliary is already at the front. After they, keep **been + measuring**.","D":"The perfect auxiliary requires been, not being."}}},{"id":"0dc1b42b-ee41-58ae-a058-093fa922c696","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Choose the past perfect SIMPLE, focusing on completion: I ____ the garden fence before lunch yesterday.","choices":[{"id":"A","text":"had been measuring"},{"id":"B","text":"had measuring"},{"id":"C","text":"had to measure"},{"id":"D","text":"had measured"}],"answerId":"D","hint":"Separate **completion** from **duration**. The requested form is perfect simple.","explanation":"The instruction focuses on a completed result, so use the simple perfect **had measured**.","keywords":["simple-continuous-contrast"],"skill":"simple-continuous-contrast","contextKey":"past-perfect-continuous-3","fingerprint":"490eb03035465ea203d51140ea6605ff13212078b6dbf414451f16dcf8821e21","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Separate **completion** from **duration**. The requested form is perfect simple.","The instruction focuses on a completed result, so use the simple perfect **had measured**.","Choose **had measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This is perfect continuous, which foregrounds the activity rather than the requested simple form.","B":"This omits been and is not a complete perfect continuous form.","C":"Have as a perfect auxiliary cannot take a to-infinitive.","D":"The instruction focuses on a completed result, so use the simple perfect **had measured**."}}},{"id":"f6e7bfa2-3d61-5999-a2dd-36351f1d506c","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Use the past perfect continuous: She ____ the travel leaflet for an hour before lunch yesterday.","choices":[{"id":"A","text":"had translating"},{"id":"B","text":"had being translating"},{"id":"C","text":"had been translated"},{"id":"D","text":"had been translating"}],"answerId":"D","hint":"An activity lasting for a period calls for the requested **perfect + continuous** form.","explanation":"Build **had + been + translating**. The sentence focuses on the duration of the activity before lunch yesterday.","keywords":["continuous-affirmative"],"skill":"continuous-affirmative","contextKey":"past-perfect-continuous-4","fingerprint":"7dfd46d815cb18626742061abdd80a069d551dc98d25d833c4243e55092246f0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["An activity lasting for a period calls for the requested **perfect + continuous** form.","Build **had + been + translating**. The sentence focuses on the duration of the activity before lunch yesterday.","Choose **had been translating**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Been is missing between the perfect auxiliary and the -ing form.","B":"The perfect auxiliary requires been, not being.","C":"A past participle here would suggest passive voice rather than the requested active continuous.","D":"Build **had + been + translating**. The sentence focuses on the duration of the activity before lunch yesterday."}}},{"id":"cd99d3d1-d645-52dd-ad9b-387fe665943a","topicSlug":"past-perfect-continuous","level":"B2","prompt":"Make a past-perfect-continuous negative: We ____ the travel leaflet all morning before lunch yesterday.","choices":[{"id":"A","text":"did not been translating"},{"id":"B","text":"had not been translating"},{"id":"C","text":"had been not translating"},{"id":"D","text":"had not translating"}],"answerId":"B","hint":"Put **not after the first auxiliary** and retain the rest of the verb phrase.","explanation":"Put not after **had**, before **been translating**.","keywords":["continuous-negative"],"skill":"continuous-negative","contextKey":"past-perfect-continuous-4","fingerprint":"a7a47ee2bf6b5568331dd7f9a92398edf23ba3f306daf63c1882806afb1d6134","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-perfect"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Put **not after the first auxiliary** and retain the rest of the verb phrase.","Put not after **had**, before **been translating**.","Choose **had not been translating**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Did cannot combine with been to make a perfect continuous negative.","B":"Put not 